            out.append((sku,b,t,q));st[sku][b]=0;st[sku][t]=st[sku].get(t,0)+q
w=csv.writer(open('/app/move-plan.csv','w'));w.writerow(['sku','from_bin','to_bin','qty']);w.writerows(out)
print(out)
